package main

import (
	"bufio"
	"fmt"
	"os"
)

const MOD = 1000000007

func power(a, b int64) int64 {
	a %= MOD
	if a < 0 {
		a += MOD
	}
	var r int64 = 1
	for b > 0 {
		if b&1 == 1 {
			r = r * a % MOD
		}
		a = a * a % MOD
		b >>= 1
	}
	return r
}

func inv(a int64) int64 {
	return power(a, MOD-2)
}

func main() {
	reader := bufio.NewReader(os.Stdin)
	var n int64
	var k int
	fmt.Fscan(reader, &n, &k)

	type pe struct {
		p int64
		e int
	}
	factors := []pe{}
	m := n
	for d := int64(2); d*d <= m; d++ {
		if m%d == 0 {
			cnt := 0
			for m%d == 0 {
				m /= d
				cnt++
			}
			factors = append(factors, pe{d, cnt})
		}
	}
	if m > 1 {
		factors = append(factors, pe{m, 1})
	}

	invs := make([]int64, 64)
	for i := 1; i < 64; i++ {
		invs[i] = inv(int64(i))
	}

	var ans int64 = 1
	for _, f := range factors {
		e := f.e
		dp := make([]int64, e+1)
		ndp := make([]int64, e+1)
		var pw int64 = 1
		for j := 0; j <= e; j++ {
			dp[j] = pw
			pw = pw * (f.p % MOD) % MOD
		}
		for step := 0; step < k; step++ {
			var pref int64 = 0
			for j := 0; j <= e; j++ {
				pref = (pref + dp[j]) % MOD
				ndp[j] = pref * invs[j+1] % MOD
			}
			dp, ndp = ndp, dp
		}
		ans = ans * dp[e] % MOD
	}
	fmt.Println(ans)
}
